const updateConservazione = `-- name: UpdateConservazione :execrows
UPDATE file_rfq_conservazione
   SET stato = $1, causa = $2, errore = $3, tentativi = $4,
       prossimo_tentativo_il = $5, sorgente_byte = COALESCE($6, sorgente_byte),
       bytes = COALESCE($7, bytes)
 WHERE conservazione_id = $8 AND stato = $9
`

type UpdateConservazioneParams struct {
	Stato               string      `json:"stato"`
	Causa               pgtype.Text `json:"causa"`
	Errore              pgtype.Text `json:"errore"`
	Tentativi           int32       `json:"tentativi"`
	ProssimoTentativoIl *time.Time  `json:"prossimo_tentativo_il"`
	SorgenteByte        pgtype.Text `json:"sorgente_byte"`
	Bytes               pgtype.Int8 `json:"bytes"`
	ConservazioneID     int64       `json:"conservazione_id"`
	StatoAtteso         string      `json:"stato_atteso"`
}

// Un passo della copia dallo stato atteso (confronta e scambia; in_copia → in_copia e' il battito). Le transizioni le
// controlla il trigger (P4X09); verificato_il e concluso_il li scrive lui.
func (q *Queries) UpdateConservazione(ctx context.Context, arg UpdateConservazioneParams) (int64, error) {
	result, err := q.db.Exec(ctx, updateConservazione,
		arg.Stato,
		arg.Causa,
		arg.Errore,
		arg.Tentativi,
		arg.ProssimoTentativoIl,
		arg.SorgenteByte,
		arg.Bytes,
		arg.ConservazioneID,
		arg.StatoAtteso,
	)
	if err != nil {
		return 0, err
	}
	return result.RowsAffected(), nil
}

const updateFileRfqStato = `-- name: UpdateFileRfqStato :execrows
UPDATE file_rfq SET stato = $1, versione = versione + 1, aggiornato_da = $2
 WHERE thread_id = $3 AND allegato_id = $4 AND versione = $5
`

type UpdateFileRfqStatoParams struct {
	Stato          string    `json:"stato"`
	UtenteID       uuid.UUID `json:"utente_id"`
	ThreadID       uuid.UUID `json:"thread_id"`
	AllegatoID     uuid.UUID `json:"allegato_id"`
	VersioneAttesa int32     `json:"versione_attesa"`
}

// Una transizione dello stato alla versione attesa (confronta e scambia: 0 righe = la versione e' cambiata, 409
// FILE_VERSIONE). Le transizioni ammesse le controlla il trigger (P4X09).
func (q *Queries) UpdateFileRfqStato(ctx context.Context, arg UpdateFileRfqStatoParams) (int64, error) {
	result, err := q.db.Exec(ctx, updateFileRfqStato,
		arg.Stato,
		arg.UtenteID,
		arg.ThreadID,
		arg.AllegatoID,
		arg.VersioneAttesa,
	)
	if err != nil {
		return 0, err
	}
	return result.RowsAffected(), nil
}

const updateRimozione = `-- name: UpdateRimozione :execrows
UPDATE file_rfq_rimozione
   SET stato = $1, motivo = $2, ritentabile = $3, errore = $4,
       tentativi = $5, prossimo_tentativo_il = $6,
       percorso_trovato = COALESCE(percorso_trovato, $7)
 WHERE rimozione_id = $8 AND stato = $9
`

type UpdateRimozioneParams struct {
	Stato               string      `json:"stato"`
	Motivo              string      `json:"motivo"`
	Ritentabile         bool        `json:"ritentabile"`
	Errore              pgtype.Text `json:"errore"`
	Tentativi           int32       `json:"tentativi"`
	ProssimoTentativoIl *time.Time  `json:"prossimo_tentativo_il"`
	PercorsoTrovato     pgtype.Text `json:"percorso_trovato"`
	RimozioneID         int64       `json:"rimozione_id"`
	StatoAtteso         string      `json:"stato_atteso"`
}

// Un passo della rimozione dallo stato atteso (confronta e scambia). percorso_trovato si scrive una volta (il trigger
// lo tiene fermo); da un errore non ritentabile si esce solo con eseguita / bonificato (trigger).
func (q *Queries) UpdateRimozione(ctx context.Context, arg UpdateRimozioneParams) (int64, error) {
	result, err := q.db.Exec(ctx, updateRimozione,
		arg.Stato,
		arg.Motivo,
		arg.Ritentabile,
		arg.Errore,
		arg.Tentativi,
		arg.ProssimoTentativoIl,
		arg.PercorsoTrovato,
		arg.RimozioneID,
		arg.StatoAtteso,
	)
	if err != nil {
		return 0, err
	}
	return result.RowsAffected(), nil
}
